const hoy = () => new Date().toISOString().split("T")[0];
const ahora = () => new Date().toLocaleTimeString("es-MX", { hour:"2-digit", minute:"2-digit" });
const fmtF = (f) => {
  if (!f) return "";
  const [y,m,d] = f.split("-");
  return d+"/"+m+"/"+y;
};
const fmtFLargo = (f) => {
  if (!f) return "";
  return new Date(f+"T12:00:00").toLocaleDateString("es-MX",{weekday:"long",day:"numeric",month:"long"});
};
const calcIMC = (p,t) => {
  if (!p||!t) return "";
  const tm = parseFloat(t)/100;
  return (parseFloat(p)/(tm*tm)).toFixed(1);
};
// Calcula la edad a partir de fecha YYYY-MM-DD
const calcEdad = (fechaNac) => {
  if (!fechaNac) return "";
  try {
    const hoy = new Date();
    const nac = new Date(fechaNac);
    if (isNaN(nac.getTime())) return "";
    let edad = hoy.getFullYear() - nac.getFullYear();
    const m = hoy.getMonth() - nac.getMonth();
    if (m < 0 || (m === 0 && hoy.getDate() < nac.getDate())) edad--;
    return edad >= 0 && edad <= 130 ? String(edad) : "";
  } catch(e) { return ""; }
};

// HOMA-IR = (Glucosa mg/dL × Insulina μU/mL) / 405
// <2.5 normal · 2.5-3.8 resistencia leve · >3.8 resistencia insulínica
const calcHOMA = (glucosa, insulina) => {
  const g = parseFloat(glucosa);
  const i = parseFloat(insulina);
  if (isNaN(g) || isNaN(i) || g <= 0 || i <= 0) return "";
  const homa = (g * i) / 405;
  return homa.toFixed(2);
};

// Enviar mensaje WhatsApp con manejo robusto de teléfono faltante o malformado
const enviarWA = (telefono, mensaje) => {
  const tel = String(telefono||"").replace(/\D/g,"");
  if (!tel || tel.length < 10) {
    try {
      navigator.clipboard.writeText(mensaje);
      alert("⚠️ Este paciente no tiene teléfono registrado.\n\nEl mensaje se copió al portapapeles. Pégalo manualmente en WhatsApp.");
    } catch(e) {
      alert("⚠️ Este paciente no tiene teléfono registrado.");
    }
    return false;
  }
  const num = tel.startsWith("52") ? tel : (tel.length===10 ? "52"+tel : tel);
  const url = "https://wa.me/"+num+"?text="+encodeURIComponent(mensaje);
  window.open(url, "_blank");
  return true;
};

// Abre Google Calendar con los datos de la cita prellenados
const agregarAGoogleCalendar = async (nombre, telefono, fecha, hora, tipoCita, duracionMin) => {
  if (isGoogleAuthorized()) {
    const resultado = await crearEventoGCal(nombre, telefono, fecha, hora, tipoCita, duracionMin);
    if (resultado) {
      alert("✅ Cita agregada a Google Calendar");
    } else {
      // Fallback: abrir URL manual
      const [year, month, day] = fecha.split("-");
      const [hr, mn] = hora.split(":");
      const ini = `${year}${month}${day}T${hr}${mn}00`;
      const iniDate = new Date(parseInt(year), parseInt(month)-1, parseInt(day), parseInt(hr), parseInt(mn));
      const finDate = new Date(iniDate.getTime() + (duracionMin||30)*60000);
      const fin = `${finDate.getFullYear()}${String(finDate.getMonth()+1).padStart(2,"0")}${String(finDate.getDate()).padStart(2,"0")}T${String(finDate.getHours()).padStart(2,"0")}${String(finDate.getMinutes()).padStart(2,"0")}00`;
      const tipo = tipoCita === "primera" ? "Primera vez" : "Seguimiento";
      const url = `https://calendar.google.com/calendar/render?action=TEMPLATE&text=${encodeURIComponent(nombre+" — "+tipo)}&dates=${ini}/${fin}&location=${encodeURIComponent("Av. Adolfo de la Huerta 200A 2do piso, Hermosillo")}`;
      window.open(url, "_blank");
    }
  } else {
    authorizeGoogleCalendar();
  }
};

const gradoIMC = (v) => {
  const n = parseFloat(v);
  if (!n) return "";
  if (n<18.5) return "Bajo peso";
  if (n<25)   return "Normal";
  if (n<30)   return "Sobrepeso";
  if (n<35)   return "Obesidad I";
  if (n<40)   return "Obesidad II";
  return "Obesidad III";
};
const diasDesde = (f) => {
  if (!f) return null;
  return Math.floor((Date.now()-new Date(f+"T00:00:00").getTime())/86400000);
};
const diasHasta = (f) => {
  if (!f) return null;
  return Math.ceil((new Date(f+"T00:00:00").getTime()-Date.now())/86400000);
};
const estadoLabs = (fecha) => {
  const d = diasDesde(fecha);
  if (d===null) return {nivel:"none",dias:null,msg:""};
  if (d>=90) return {nivel:"rojo",dias:d,msg:"Labs vencidos hace "+(d-90)+" días"};
  if (d>=80) return {nivel:"amarillo",dias:d,msg:"Labs vencen en "+(90-d)+" días"};
  return {nivel:"verde",dias:d,msg:"Labs al día"};
};

